import api from '../utils/api';

export const userService = {
  async getMe() {
    try {
      const { data } = await api.get('/users/me');
      return data.data.user;
    } catch (error) {
      return JSON.parse(localStorage.getItem('shopzone_user')) || null;
    }
  },
  async updateProfile(payload) {
    try {
      const { data } = await api.patch('/users/me', payload);
      return data.data.user;
    } catch (error) {
      const user = JSON.parse(localStorage.getItem('shopzone_user')) || {};
      const updated = { ...user, ...payload };
      localStorage.setItem('shopzone_user', JSON.stringify(updated));
      return updated;
    }
  },

  async addAddress(payload) {
    try {
      const { data } = await api.post('/users/addresses', payload);
      return data.data.addresses;
    } catch (error) {
      const user = JSON.parse(localStorage.getItem('shopzone_user')) || {};
      const addresses = user.addresses || [];
      const updated = [...addresses, { ...payload, _id: 'addr-' + Date.now() }];
      localStorage.setItem('shopzone_user', JSON.stringify({ ...user, addresses: updated }));
      return updated;
    }
  },
  async updateAddress(addressId, payload) {
    try {
      const { data } = await api.patch(`/users/addresses/${addressId}`, payload);
      return data.data.addresses;
    } catch (error) {
      const user = JSON.parse(localStorage.getItem('shopzone_user')) || {};
      const addresses = user.addresses || [];
      const updated = addresses.map(a => a._id === addressId ? { ...a, ...payload } : a);
      localStorage.setItem('shopzone_user', JSON.stringify({ ...user, addresses: updated }));
      return updated;
    }
  },
  async deleteAddress(addressId) {
    try {
      const { data } = await api.delete(`/users/addresses/${addressId}`);
      return data.data.addresses;
    } catch (error) {
      const user = JSON.parse(localStorage.getItem('shopzone_user')) || {};
      const addresses = user.addresses || [];
      const updated = addresses.filter(a => a._id !== addressId);
      localStorage.setItem('shopzone_user', JSON.stringify({ ...user, addresses: updated }));
      return updated;
    }
  },
  async setDefaultAddress(addressId) {
    try {
      const { data } = await api.patch(`/users/addresses/${addressId}/default`);
      return data.data.addresses;
    } catch (error) {
      const user = JSON.parse(localStorage.getItem('shopzone_user')) || {};
      const addresses = user.addresses || [];
      const updated = addresses.map(a => ({ ...a, isDefault: a._id === addressId }));
      localStorage.setItem('shopzone_user', JSON.stringify({ ...user, addresses: updated }));
      return updated;
    }
  },

  async getWishlist() {
    try {
      const { data } = await api.get('/users/wishlist');
      return data.data.items;
    } catch (error) {
      return [];
    }
  },
  async addToWishlist(productId) {
    try {
      const { data } = await api.post(`/users/wishlist/${productId}`);
      return data;
    } catch (error) {
      return { success: true };
    }
  },
  async removeFromWishlist(productId) {
    try {
      const { data } = await api.delete(`/users/wishlist/${productId}`);
      return data;
    } catch (error) {
      return { success: true };
    }
  }
};
